insert into public.postings (kind, platform, title, author, excerpt, url, thumbnail_url, posted_on, published) values
  ('club', 'naver_cafe', '[2012-2013시즌 FK리그] 서울 은평FS 풋볼아카데미 참가확정', '풋볼아카데미', 'SEOUL EUNPYEONG FS FUTBOL ACADEMY 2012 - 2013시즌 FK리그 [한국 풋살 프로리그] 참가확정 대한축구협회(KFA) FK리그[한국 풋살 프로리그] 정식 팀 등록 (2012. 6. 26 부.)... COM [90플러스] [의류 및 장비 지원] 의료법인 은평청구성심병원 [의료지원] 대한민국 대표 스포츠 프로그램 FUTBOL ACADEMY [재정지원] FUTBOL ACADEMY (주) 현대글로벌로직스 DOSOCCER.COM 서울 은평FS 풋볼아카데미 구단', 'https://cafe.naver.com/soccerholics/952', null, '2012-06-29', true),
  ('fan', 'naver_cafe', '[FK 컵]FS서울 : 서울은평FS 12년 7월29일', '파란 Football Club', '', 'https://cafe.naver.com/fcivy/575', null, '2012-08-10', true),
  ('news', 'article', '서울 은평FS 풋볼아카데미 구단 공식 창단', '쿠키뉴스', '[쿠키 생활] 한국풋살연맹이 주관하고 대한축구협회와 국민체육진흥공단이 후원하는 대한민국 풋살프로리그 ‘FK리그’에 참가하는 서울은평FS 풋볼아카데미 구단이 공식 창단식을 가졌다. 서울은평FS 풋볼아카데미 구단은 서울시 은평구를 연고로 은평구민체육센터를 홈구장으로 쓰고 있으며, 해외... 서울 은평FS 풋볼아카데미 구단 공식 창단 머니투데이 2012.11.19. 네이버뉴스', 'http://news.kukinews.com/article/view.asp?page=1&gCode=cul&arcid=0006640945&cp=nv', 'https://vunnzagbsrujdernvetl.supabase.co/storage/v1/object/public/media/postings/a69d3e49343d2c62.jpg', '2012-11-19', true),
  ('news', 'article', '서울 은평FS 풋볼아카데미 구단 공식 창단', '머니투데이', '머니투데이 2012.11.19. 네이버뉴스', 'http://www.mt.co.kr/view/mtview.php?type=1&no=2012111911205375697&outlink=1', 'https://vunnzagbsrujdernvetl.supabase.co/storage/v1/object/public/media/postings/128f3652c05bd29c.jpg', '2012-11-19', true),
  ('news', 'article', '현대글로벌로직스, 풋볼구단 창단', '한국경제', '수출입물류기업인 현대글로벌로직스(대표 손문승)는 최근 서울 은평FS 풋볼아카데미구단을 창단했다. 이 구단은 풋살프로리그 FK리그에 오는 24일부터 참가한다. ⓒ 한국경제신문,', 'http://www.hankyung.com/news/app/newsview.php?aid=2012112049041', null, '2012-11-20', true),
  ('news', 'naver_blog', '2012-2013 FK리그 개막... 4개월 간의 대장정 돌입!', '2011-12 FK LEAGUE 블로그', '2012-13 시즌은 은평 FS, 부천 FS, 제천 FS을 새로운 식구로 받아들여 기존의 FS 서울, 전주 매그 풋살, 경산 오성 FC, 용인 FS, 서울 광진 풋살, 예스 구미 FC 등 총 9개 팀이 참가하는 역대... 이번 대회 첫 출전한 팀들 간의 경기에서 부천 FS는 이두용의 헤트트릭에 힘 입어 서울 은평 FS에 5:4의 짜릿한 승리를 거뒀고, 용인 FS는 경산 오성 FC를 서울 광진 풋살은 예스 구미 FC를...', 'https://blog.naver.com/futsal2010/50155544689', 'https://vunnzagbsrujdernvetl.supabase.co/storage/v1/object/public/media/postings/1ae889725302164f.jpg', '2012-11-24', true),
  ('fan', 'naver_cafe', '[2012-13 FK리그] 은평FS : 부천FS', '파란 Football Club', '하이라이트 경기영상', 'https://cafe.naver.com/fcivy/743', null, '2012-11-26', true),
  ('fan', 'naver_cafe', '2012-2013년도 FK리그 소식', '운영 풋살교실(태성고등학교)', '[2013-01-22] 서울 은평 FS, 제천 FS 상대로 치열한 접전 끝 승리! 서울 은평 FS가 충북 보은 실내체육관에서 계속되고 있는 2012-2013 FK리그에서 종료 직전 터진 최경진의 역전골에 힘입어 제천 FS에 6... [2013-01-17] FS 서울, 예스 구미 상대로 승리. 강자의 면모 되찾나! FS 서울은 충북 보은 실내체육관에서 펼쳐지고 있는 2012-2013 FK리그 경기에서 최하위 예스 구미 FC를 상대로 9:3의 완승을 거두며...', 'https://cafe.naver.com/ytfutsal/286', null, '2013-02-08', true),
  ('fan', 'naver_cafe', '[FK리그] 은평FS : 용인FS', 'WONJU F·S CLUB 원주풋살클럽', '', 'https://cafe.naver.com/wjfsclub/185', null, '2013-02-16', true),
  ('fan', 'naver_cafe', '[FK리그] FS서울 : 은평FS', 'WONJU F·S CLUB 원주풋살클럽', '', 'https://cafe.naver.com/wjfsclub/202', null, '2013-02-16', true),
  ('fan', 'naver_cafe', '◆ 경축 ◆ 서울은평FS 프로풋살구단 2012-13 FK리그 페어플레이팀 수상', '샬롬코리아사커스쿨 - 대구유소년축구교실', '대구유소년축구교실의 메카 샬롬코리아 사커스쿨 총 감독 김영준 감독님께서 이끄시는 서울 은평FS 프로풋살구단이 2012-13 현대해상 FK리그 페어플레이팀 수상과 더불어 최경진 선수의 2012-13시즌 득정왕 및 2013 인천 무도 아시안게임 국가대표 3명을 배출하게 되었습니다. 사커스쿨 가족들에 많은 관심과 사랑 부탁 드리며 훗날 SKSS코칭스탭출신 대한축구협회 전임 강사 및 성인 국가대표 감독을 꿈꾸며...', 'https://cafe.naver.com/shalomkor/1702', null, '2013-04-06', true),
  ('news', 'article', '공 따로 몸 따로', '연합뉴스', '2일 오후 경남 남해군 상주면 은모래해수욕장에서 열린 2013 하이트진로 진국비치사커대회에서 서울은평FS풋볼아카데미팀과 FC양윤팀 선수가 뜬공을 먼저 처리하기 위해 함께 발을 들고 있다. 2013.8.2 choi21@yna.co.kr', 'https://m.sports.naver.com/general/article/001/0006408319', 'https://vunnzagbsrujdernvetl.supabase.co/storage/v1/object/public/media/postings/e314dad26675061f.jpg', '2013-08-02', true),
  ('news', 'article', '모래 위 축구 열전', '연합뉴스', '2일 오후 경남 남해군 상주면 은모래해수욕장에서 열린 2013 하이트진로 진국비치사커대회에서 서울은평FS풋볼아카데미팀과 FC양윤팀 선수가 열전을 펼치고 있다. 2013.8.2 choi21@yna.co.kr 모래 위 열전 연합뉴스 2013.08.02. 네이버뉴스 해수욕장 모래 위 축구 열전 연합뉴스 2013.08.02. 네이버뉴스 해수욕장 모래 위 몸싸움 연합뉴스 2013.08.02. 네이버뉴스 해수욕장 모래 위 열전 연합뉴스 2013.08.02. 네이버뉴스', 'https://m.sports.naver.com/general/article/001/0006408323', 'https://vunnzagbsrujdernvetl.supabase.co/storage/v1/object/public/media/postings/ac13679fa0a1466f.jpg', '2013-08-02', true),
  ('news', 'article', '2013 전국비치사커대회', '연합뉴스', '2일 오후 경남 남해군 상주면 은모래해수욕장에서 열린 2013 하이트진로 진국비치사커대회에서 서울은평FS풋볼아카데미팀(왼쪽)과 FC양윤팀 선수가 열전을 펼치고 있다. 2013.8.2 choi21@yna.co.kr 2013 전국비치사커대회 연합뉴스 2013.08.02. 네이버뉴스 비치 위 치열한 몸싸움 연합뉴스 2013.08.02. 네이버뉴스', 'https://m.sports.naver.com/general/article/001/0006408329', 'https://vunnzagbsrujdernvetl.supabase.co/storage/v1/object/public/media/postings/c8fe23e674a452fd.jpg', '2013-08-02', true),
  ('fan', 'naver_cafe', '[FK리그] 서울은평FS : 예스구미FS', '아라풋살클럽', '', 'https://cafe.naver.com/ahraclub/892', null, '2013-12-20', true),
  ('fan', 'naver_blog', '[FK리그] FS서울 VS 서울은평FS', '君にとどけ！', '29 FS서울 VS 서울은평FS - 경기결과 : 5-5 무! - FS서울 출전선수 : 김민국, 김학원, 허명범, 이종민, 서대윤 (서대윤 3골, 김민국 1골, 김무현 1골) - 서울은평FS 출전선수 : 최경진... 마지막에 1골만 먹히지 않았어도....ㅠㅠㅠㅠ 경기 초반 은평의 맹공세로 0-4... 축구라면 패색이 짙은 경기였으나...풋살은 다르더라구요.... 10번 서대윤 선수가 17분, 19분, 20분에 3골을...', 'https://blog.naver.com/soccerlove4u/110182334833', 'https://vunnzagbsrujdernvetl.supabase.co/storage/v1/object/public/media/postings/2c16fdfcd1d0daaa.jpg', '2013-12-29', true),
  ('fan', 'naver_cafe', '2013-2014 FK리그 은평FS vs FS서울', '아이비 풋살클럽', '', 'https://cafe.naver.com/ivyfutsal/693', null, '2013-12-31', true),
  ('fan', 'naver_cafe', '[FK리그] 서울은평FS:FS서울', '파란 Football Club', '', 'https://cafe.naver.com/fcivy/1256', null, '2014-01-01', true),
  ('news', 'naver_blog', '[MOM] 현대해상 2013-14 FK리그 6라운드 판타지아부천FS vs 서울은평FS(2014.01.04.토) - 서울은평FS 9번 주훈진선수', '너와 나, 우리의 FK League', '각 조 2위의 대결로 기대를 모았던 판타지아부천FS와 서울은평FS의 경기는 4:9로 서울은평FS의 승리로 마무리되었다. 전반 2분 첫 번째 골을 터뜨린데 이어 후반 3분 추가골을 기록하며 팀 승리에 일등공신을 한 서울은평FS 주훈진선수의 얘기를 들어본다. 이름 : 주훈진 소속 : 서울은평FS 1985.06.10 177cm 70kg <주훈진선수 제공> 주훈진선수에게 승리소감에 대해 묻자...', 'https://blog.naver.com/ourfkleague/110182850035', 'https://vunnzagbsrujdernvetl.supabase.co/storage/v1/object/public/media/postings/318e7029c6f60e78.jpg', '2014-01-07', true),
  ('news', 'naver_blog', '[MOM] 현대해상 2013-14 FK리그 7라운드 서울은평FS vs 대구오성FC (2014.01.05.일) - 서울은평FS 11번 최경진선수', '너와 나, 우리의 FK League', '서울은평FS 와 대구오성FC의 7라운드 첫 번째 경기는 6-4로 서울은평FS의 승리로 끝났다. 6,7라운드 이틀 연속 승리를 이어가는데 일등 공신 서울은평FS의 최경진선수 이야기를 들어보았다. 이름 : 최경진 소속 : 서울은평FS 1984.08.12 178cm 70kg <최경진선수 제공> ''지난 부천과의 경기에서 비교적 쉬운 승리를 거뒀다면, 오늘 경기는 피로누적과 컨디션 난조로 골찬스를...', 'https://blog.naver.com/ourfkleague/110183042494', 'https://vunnzagbsrujdernvetl.supabase.co/storage/v1/object/public/media/postings/a10d71e373d3b934.jpg', '2014-01-09', true),
  ('news', 'article', '''FK리그 12-13R'' 제천FS, 2연승 거두고 1위 질주', 'STN 뉴스', '나란히 B조 2위와 3위를 달리고 있는 서울은평FS와 FS서울은 1승 1패로 주말경기를 마무리했다. 맞대결로 펼쳐진 25일 경기에서 서울은평FS는 득점랭킹 1위를 달리고 있는 최경진이 혼자서 4골을 몰아쳐 짜릿한 6-5 승리를 거뒀다. 그러나 B조 4위의 용인FS에 7-6으로 일격을 당하면서 상승세를...', 'https://m.sports.naver.com/general/article/450/0000000393', 'https://vunnzagbsrujdernvetl.supabase.co/storage/v1/object/public/media/postings/4912f70b0e40aee2.jpg', '2014-01-26', true),
  ('news', 'article', '''FK리그 14R'' 용인FS, 예스구미FC꺾고 선두권 추격', 'STN 뉴스', 'B조 4위와 최하위를 달리고 있는 서울은평FS와 IFC대전의 경기에서는 5골을 넣은 최경진의 활약에 힘입어 서울은평FS가 12-2로 낙승을 거뒀다. 서울은평FS는 최경진 외에도 이영진(3골), 최용환(2골)이 공격에서 힘을 보태면서 손쉬운 승리를 거뒀다. 반면 IFC대전은 수비에서 무너지며 연패횟수를 15로...', 'https://m.sports.naver.com/general/article/450/0000000911', 'https://vunnzagbsrujdernvetl.supabase.co/storage/v1/object/public/media/postings/6fb17838f12e48a7.jpg', '2014-02-16', true),
  ('news', 'naver_blog', '[MOM] 현대해상 2013-14 FK리그 14라운드(B조) 서울은평FS vs IFC대전 (2014.02.15.토) - 서울은평FS 10번 이영진선수', '너와 나, 우리의 FK League', '우리 팀의 목표는 9부능선을 넘었고, 남은 충북제천FS,예스구미FS 강팀들과의 경기에서 최선을 다해 플레이오프 진출을 꼭 이루고 싶다'' 고 각오를 밝힌 이영진선수. 지난 시즌의 아쉬움을 올 시즌에 아낌없이 보여주고 있는 서울은평FS팀 리그 마지막까지 아끼없는 응원을 보낸다. "풋살이란 스포츠, 다소 생소할 수 있지만 직접 보러 오시면 그 생각이 달라지실...', 'https://blog.naver.com/ourfkleague/110185936142', 'https://vunnzagbsrujdernvetl.supabase.co/storage/v1/object/public/media/postings/87d211e6016ff84d.jpg', '2014-02-24', true),
  ('news', 'article', '‘FK리그 16R’ 서울은평, 예스구미 꺾고 천신만고 끝에 플레이오프 진...', 'STN 뉴스', '서울은평FS가 예스구미FC를 꺾고 B조 2위로 플레이오프 진출을 확정지었다. 서울은평은 1일 영월 스포츠파크 실내체육관에서 열린 현대해상 2013-14 FK리그 16라운드 예스구미와의 경기에서 접전 끝에 5-3 승리를 거두고 B조 2위로 플레이오프에 진출했다. 예스구미와의 경기에서 승리한다면 자력으로...', 'https://m.sports.naver.com/general/article/450/0000001219', 'https://vunnzagbsrujdernvetl.supabase.co/storage/v1/object/public/media/postings/77d2ecc4d7d4a43f.jpg', '2014-03-01', true),
  ('news', 'article', '‘신종훈 멀티골’ 전주매그, 은평FS꺾고 챔피언결정전 선착', 'STN 뉴스', '전주매그클럽이 멀티골을 기록한 신종훈의 활약을 앞세워 서울은평FS를 꺾고 챔피언결정전 진출에 성공했다. 전주매그풋살클럽은 8일 파주NFC풋살구장에서 열린 현대해상 2013-14 FK리그 서울은평FS와의 플레이오프 1차전 경기에서 5-3의 역전승을 거두고 챔피언결정전 진출에 성공했다. 리그 16전...', 'https://m.sports.naver.com/general/article/450/0000001502', 'https://vunnzagbsrujdernvetl.supabase.co/storage/v1/object/public/media/postings/28b917211dac8285.jpg', '2014-03-08', true),
  ('fan', 'naver_cafe', '2013-2014 FK리그 예스구미 vs 은평FS', '아이비 풋살클럽', '', 'https://cafe.naver.com/ivyfutsal/789', null, '2014-03-09', true),
  ('news', 'naver_blog', '[MOM] 현대해상 2013-14 FK리그 플레이오프 전주매그풋살클럽 vs 서울은평FS (2014.03.08.토) - 전주매그풋살클럽 30번 신종훈선수', '너와 나, 우리의 FK League', '현대해상 2013-14 FK 리그 플레이오프 첫 번째 경기 A조1위 전주매그풋살클럽과 B조2위 서울은평FS의 경기는 5대3으로 전주매그풋살클럽이 승리하며 챔피언결정전 진출을 확정지었다.... 이번 챔피언결정전 역시 나의 모든 것을 쏟아붓는다는 각오로 경기에 임할 예정이다.'' 고 챔피언결정전에 임하는 각오를 다진 신종훈선수는 ''상대팀인 충북제천FS의 경우 선수들...', 'https://blog.naver.com/ourfkleague/110187034612', 'https://vunnzagbsrujdernvetl.supabase.co/storage/v1/object/public/media/postings/527fae679acb0f9f.jpg', '2014-03-13', true),
  ('news', 'article', '전주매그, 제천FS와 FK리그 챔피언결정전에서 격돌', 'STN 뉴스', '먼저 전주매그풋살클럽이 서울은평FS를 제치고 챔프전 결승 무대에 올랐습니다. 전주매그는 파상공세를 펼치며 상대를 밀어붙였지만 선제골은 서울은평의 몫이었습니다. 서울은평 주훈진이 득점포를 가동하며 기선 제압에 성공한 것입니다. 그것도 잠시 전주매그는 주포 신종훈을 앞세워...', 'https://m.sports.naver.com/general/article/450/0000001764', null, '2014-03-14', true),
